package com.witchersbestiary.test;
import com.witchersbestiary.signs.*;import com.witchersbestiary.sorcery.*;import com.witchersbestiary.contracts.*;import com.witchersbestiary.contracts.procedural.*;import com.witchersbestiary.contracts.tracking.*;
import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.test.*;import net.minecraft.entity.*;import net.minecraft.entity.mob.*;import net.minecraft.entity.attribute.EntityAttributes;import net.minecraft.entity.effect.*;import net.minecraft.item.*;import net.minecraft.block.Blocks;import net.minecraft.util.math.*;import net.minecraft.registry.*;import java.util.*;
public final class Stage21ITests implements FabricGameTest {
 private net.minecraft.server.network.ServerPlayerEntity player(TestContext c){var data=net.minecraft.server.network.ConnectedClientData.createDefault(new com.mojang.authlib.GameProfile(UUID.randomUUID(),"sorcery"),false);var p=new net.minecraft.server.network.ServerPlayerEntity(c.getWorld().getServer(),c.getWorld(),data.gameProfile(),data.syncedOptions());var connection=new net.minecraft.network.ClientConnection(net.minecraft.network.NetworkSide.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(connection);p.getServer().getPlayerManager().onPlayerConnect(connection,p,data);p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);for(int i=0;i<61;i++)p.tick();p.setHealth(20);p.setNoGravity(true);var at=c.getAbsolutePos(new BlockPos(6,2,6));p.refreshPositionAndAngles(at.getX()+.5,at.getY(),at.getZ()+.5,0,0);for(var sign:SignType.values())SignManager.state(p).learn(sign);return p;}
 private MobEntity mob(TestContext c,net.minecraft.server.network.ServerPlayerEntity p,EntityType<? extends MobEntity> type){var e=type.create(c.getWorld());e.refreshPositionAndAngles(p.getX(),p.getY(),p.getZ()+3,180,0);e.setNoGravity(true);e.setAiDisabled(true);e.equipStack(EquipmentSlot.HEAD,new ItemStack(Items.CARVED_PUMPKIN));e.setPersistent();c.getWorld().spawnEntity(e);return e;}
 @GameTest(templateName="witchersbestiary:village_board_arena",tickLimit=500,batchId="stage21i-contracts") public void allTwelveSpeciesAnyBiomeBoardBoundRouteUniqueSpawn(TestContext c){var w=c.getWorld();var origin=c.getAbsolutePos(new BlockPos(0,2,0));var plains=w.getRegistryManager().get(RegistryKeys.BIOME).getEntry(net.minecraft.world.biome.BiomeKeys.PLAINS).orElseThrow();for(int x=-8;x<=110;x++)for(int z=-35;z<=35;z++){var at=origin.add(x,0,z);w.getChunk(at);w.setBlockState(at.down(),Blocks.GRASS_BLOCK.getDefaultState());for(int y=0;y<9;y++)w.setBlockState(at.up(y),Blocks.AIR.getDefaultState());}for(int x=(origin.getX()-8)>>4;x<=(origin.getX()+110)>>4;x++)for(int z=(origin.getZ()-35)>>4;z<=(origin.getZ()+35)>>4;z++){w.setChunkForced(x,z,true);w.getChunk(x,z).populateBiomes((a,b,d,s)->plains,w.getChunkManager().getNoiseConfig().getMultiNoiseSampler());}var p=c.createMockCreativeServerPlayerInWorld();p.refreshPositionAndAngles(origin.getX()+4,origin.getY(),origin.getZ(),0,0);var kinds=new ArrayList<>(new TreeSet<>(ContractSpecies.ENTITIES.keySet()));final int[] index={0};final ContractInstance[] pending={null};c.runAtEveryTick(()->{
 if(pending[0]!=null){var instance=pending[0];var target=(MobEntity)w.getEntity(instance.hunt.target);if(target==null)return;c.assertTrue(target.isAlive()&&ProceduralHunts.binding(target).equals(instance.id()),"Real bound entity "+kinds.get(index[0]));Contracts.cancel(p,instance.id());pending[0]=null;index[0]++;return;}
 if(index[0]>=kinds.size()){for(int x=(origin.getX()-8)>>4;x<=(origin.getX()+110)>>4;x++)for(int z=(origin.getZ()-35)>>4;z<=(origin.getZ()+35)>>4;z++)w.setChunkForced(x,z,false);p.discard();c.complete();return;}
 String kind=kinds.get(index[0]);var instance=Contracts.assignPrepared(p,ProceduralHunts.id(kind),215L,origin);var route=instance.investigation;c.assertTrue(instance.hunt.origin.equals(origin)&&route.clues.size()==2&&instance.hunt.target==null,"Board-owned two-clue route: "+kind);var first=route.clues.getFirst();var second=route.clues.getLast();double gap=first.position.toCenterPos().subtract(second.position.toCenterPos()).horizontalLength();c.assertTrue(gap>=40&&gap<=60&&Investigations.view(p).has("area"),"Immediate HUD and spacing "+kind);for(var point:List.of(first.position,second.position,route.lair)){var delta=point.subtract(origin);c.assertTrue((long)delta.getX()*delta.getX()+(long)delta.getZ()*delta.getZ()<=350*350,"350 bound "+kind);}for(var clue:route.clues){p.refreshPositionAndAngles(clue.position.getX()+.5,clue.position.getY(),clue.position.getZ()+.5,0,0);c.assertTrue(Investigations.inspect(p,clue.id),"Sequential clue "+kind);}var at=route.lair;p.refreshPositionAndAngles(at.getX()+.5,at.getY(),at.getZ()+3,0,0);c.assertTrue(Investigations.trySpawn(p,instance),"Forced contract spawn on plains "+kind);var id=instance.hunt.target;c.assertTrue(id!=null&&!Investigations.trySpawn(p,instance)&&ContractInstance.fromNbt(instance.toNbt()).hunt.target.equals(id),"Unique persisted UUID "+kind);pending[0]=instance;
 });}

 @GameTest(templateName="witchersbestiary:village_board_arena") public void vanillaHostilityAndFriendlyProtection(TestContext c){var p=player(c);for(var type:List.of(EntityType.ZOMBIE,EntityType.SKELETON,EntityType.CREEPER,EntityType.HOGLIN)){var e=mob(c,p,type);c.assertTrue(SignManager.enemy(p,e),"General hostile classification "+type);SignManager.state(p).select(SignType.IGNI);for(int i=0;i<500;i++)SignManager.state(p).tick();e.timeUntilRegen=0;float before=e.getHealth();c.assertTrue(SignManager.cast(p,e.getId())&&e.getHealth()<before&&e.isOnFire(),"Real Igni against "+type);e.discard();}var villager=mob(c,p,EntityType.VILLAGER);var cow=mob(c,p,EntityType.COW);var trader=mob(c,p,EntityType.WANDERING_TRADER);var wolf=(net.minecraft.entity.passive.WolfEntity)mob(c,p,EntityType.WOLF);wolf.setOwner(p);wolf.setTarget(p);c.assertTrue(!SignManager.enemy(p,villager)&&!SignManager.enemy(p,cow)&&!SignManager.enemy(p,trader)&&!SignManager.enemy(p,wolf),"Residents/merchant/peaceful/tamed ally protected");for(var e:List.of(villager,cow,trader,wolf))e.discard();p.discard();c.complete();}
 @GameTest(templateName="witchersbestiary:village_board_arena",tickLimit=220) public void quenCannotRefreshWhileActive(TestContext c){var p=player(c);SignManager.state(p).select(SignType.QUEN);c.assertTrue(SignManager.cast(p,1),"Initial Quen");c.runAtTick(170,()->{c.assertTrue(!SignManager.cast(p,2),"Cooldown elapsed but active shield cannot refresh");var source=c.getWorld().getDamageSources().fall();c.assertTrue(SignManager.protect(p,source,10)==0&&SignManager.protect(p,source,1)==1,"Exactly ten HP shield");p.discard();c.complete();});}
 @GameTest(templateName="witchersbestiary:village_board_arena",tickLimit=90) public void overlappingYrdenHasOnePulsePerTargetPerFortyTicks(TestContext c){var a=player(c);var b=player(c);b.refreshPositionAndAngles(a.getX(),a.getY(),a.getZ(),0,0);c.getWorld().setBlockState(a.getBlockPos().down(),Blocks.STONE.getDefaultState());var e=mob(c,a,EntityType.CREEPER);e.setPosition(a.getX()+1,a.getY(),a.getZ());for(var p:List.of(a,b)){SignManager.state(p).select(SignType.YRDEN);c.assertTrue(SignManager.cast(p,1),"Both traps created");}c.runAtTick(15,()->c.assertTrue(e.getHealth()>=19&&e.getHealth()<20&&e.hasStatusEffect(StatusEffects.SLOWNESS),"One damage pulse across overlapping traps"));c.runAtTick(35,()->c.assertTrue(e.getHealth()>=19,"No early second pulse"));c.runAtTick(60,()->{c.assertTrue(e.getHealth()>=18&&e.getHealth()<19,"Second two-second pulse");e.discard();a.discard();b.discard();c.complete();});}
 @GameTest(templateName="witchersbestiary:village_board_arena",tickLimit=100) public void grimoireFreeLearningCastCostControlAndPersistence(TestContext c){var p=player(c);c.assertTrue(!Sorcery.learn(p),"No forged book learning");p.getInventory().setStack(0,new ItemStack(com.witchersbestiary.registry.ModItems.GRIMOIRE));p.getInventory().setStack(1,new ItemStack(Items.AMETHYST_SHARD,2));c.assertTrue(Sorcery.learn(p)&&Sorcery.learn(p),"Free idempotent learning");var e=mob(c,p,EntityType.ZOMBIE);c.assertTrue(Sorcery.cast(p)&&!Sorcery.cast(p)&&e.getHealth()<20&&e.hasStatusEffect(StatusEffects.SLOWNESS),"Actual spell and cooldown");c.assertTrue(p.getInventory().getStack(1).getCount()==1&&SignManager.state(p).concentration()==100,"One shard, independent signs");var ledger=SorceryLedger.get(p.getServer());var saved=SorceryLedger.read(ledger.writeNbt(new net.minecraft.nbt.NbtCompound(),c.getWorld().getRegistryManager()),c.getWorld().getRegistryManager());c.assertTrue(saved.player(p.getUuid()).learned&&saved.player(p.getUuid()).cooldown==160,"Persistent learning/cooldown");c.runAtTick(70,()->{c.assertTrue(!e.hasStatusEffect(StatusEffects.SLOWNESS),"Normal movement restored");p.discard();e.discard();c.complete();});}
 @GameTest(templateName="witchersbestiary:village_board_arena") public void icyGraspBlocksWallAndPvpWithoutSpending(TestContext c){var p=player(c);p.getInventory().setStack(0,new ItemStack(com.witchersbestiary.registry.ModItems.GRIMOIRE));p.getInventory().setStack(1,new ItemStack(Items.AMETHYST_SHARD,2));Sorcery.learn(p);var e=mob(c,p,EntityType.CREEPER);for(int x=-1;x<=1;x++)for(int y=0;y<4;y++)c.getWorld().setBlockState(p.getBlockPos().add(x,y,1),Blocks.STONE.getDefaultState());c.assertTrue(!Sorcery.cast(p)&&e.getHealth()==20&&p.getInventory().getStack(1).getCount()==2,"Wall denies damage and cost");var q=player(c);boolean old=p.getServer().isPvpEnabled();try{p.getServer().setPvpEnabled(false);c.assertTrue(!SignManager.enemy(p,q),"Sorcery shares server PvP protection");}finally{p.getServer().setPvpEnabled(old);}e.discard();q.discard();p.discard();c.complete();}
 @GameTest(templateName="witchersbestiary:village_board_arena",tickLimit=1600,batchId="stage21i-async") public void unloadedSurveyCompletesWithoutBlockingAcceptance(TestContext c){var p=c.createMockCreativeServerPlayerInWorld();var origin=new BlockPos(24000,100,24000);p.refreshPositionAndAngles(origin.getX(),origin.getY(),origin.getZ(),0,0);var w=c.getWorld();c.assertTrue(w.getChunkManager().getWorldChunk((origin.getX()+80)>>4,origin.getZ()>>4)==null,"Remote patch initially unloaded");final ContractInstance[] accepted={null};final Boolean[] done={null};com.witchersbestiary.contracts.hunt.HuntTerrain.request(p,origin,()->true,()->{try{accepted[0]=Contracts.assignPrepared(p,ProceduralHunts.id("werewolf"),215L,origin);return true;}catch(IllegalStateException e){return false;}},success->{done[0]=success;});c.addInstantFinalTask(()->{c.assertTrue(Boolean.TRUE.equals(done[0])&&accepted[0]!=null&&accepted[0].investigation.clues.size()==2,"Asynchronous unloaded patch produces executable route");Contracts.cancel(p,accepted[0].id());p.discard();});c.assertTrue(com.witchersbestiary.contracts.hunt.HuntTerrain.pending(p.getUuid())&&accepted[0]==null,"Acceptance is deferred; request does not block server tick");}

 @GameTest(templateName="witchersbestiary:village_board_arena",batchId="stage21i-surfaces") public void gravelSnowAndIceArePhysicalSurfacesButHazardsAreNot(TestContext c){var at=c.getAbsolutePos(new BlockPos(12,2,12));var w=c.getWorld();for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++){w.setBlockState(at.add(x,-2,z),Blocks.GRASS_BLOCK.getDefaultState());for(int y=0;y<9;y++)w.setBlockState(at.add(x,y,z),Blocks.AIR.getDefaultState());}for(var floor:List.of(Blocks.GRAVEL,Blocks.SNOW_BLOCK,Blocks.ICE,Blocks.PACKED_ICE,Blocks.BLUE_ICE,Blocks.SNOW,Blocks.POWDER_SNOW,Blocks.LAVA,Blocks.OAK_PLANKS)){for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++)w.setBlockState(at.add(x,-1,z),floor.getDefaultState());boolean supported=floor!=Blocks.POWDER_SNOW&&floor!=Blocks.LAVA&&floor!=Blocks.OAK_PLANKS;c.assertTrue(Investigations.safeClue(w,at)==supported,"Clue surface "+floor);for(String kind:ContractSpecies.ENTITIES.keySet()){var profile=ProceduralProfile.generate(215L,kind);var instance=new ContractInstance(UUID.randomUUID(),UUID.randomUUID(),Contracts.DEFINITIONS.find(ProceduralHunts.id(kind)),System.currentTimeMillis());instance.procedural=profile;c.assertTrue(ProceduralHunts.safe(w,instance,at)==supported,"Physical footprint "+kind+" / "+floor);}}c.complete();}

 @GameTest(templateName="witchersbestiary:village_board_arena") public void sorceryRejectsOfficialFightsForgedSessionsAndPacketReplay(TestContext c)throws Exception{var p=player(c);var home=p.getPos();p.getInventory().setStack(0,new ItemStack(com.witchersbestiary.registry.ModItems.GRIMOIRE));p.getInventory().setStack(1,new ItemStack(Items.AMETHYST_SHARD,2));Sorcery.learn(p);var e=mob(c,p,EntityType.CREEPER);p.getInventory().selectedSlot=8;var npc=com.witchersbestiary.fist.FistRegistry.NOVICE.create(c.getWorld());npc.refreshPositionAndAngles(p.getX()+1,p.getY(),p.getZ(),0,0);c.getWorld().spawnEntity(npc);com.witchersbestiary.fist.FistFights.invite(p,npc);c.assertTrue(com.witchersbestiary.fist.FistFights.confirm(p,npc)&&!Sorcery.cast(p)&&Sorcery.state(p).cooldown==0&&p.getInventory().getStack(1).getCount()==2,"Official fight blocks sorcery before payment");com.witchersbestiary.fist.FistFights.cancel(p);npc.discard();p.refreshPositionAndAngles(home.x,home.y,home.z,0,0);var method=Sorcery.class.getDeclaredMethod("runtime",net.minecraft.server.network.ServerPlayerEntity.class);method.setAccessible(true);var runtime=method.invoke(null,p);var field=runtime.getClass().getDeclaredField("session");field.setAccessible(true);var session=(UUID)field.get(runtime);Sorcery.intent(p,new SorceryPackets.Intent(UUID.randomUUID(),1,1));c.assertTrue(Sorcery.state(p).cooldown==0,"Forged session cannot cast");var packet=new SorceryPackets.Intent(session,2,1);Sorcery.intent(p,packet);float after=e.getHealth();Sorcery.intent(p,packet);c.assertTrue(after<20&&e.getHealth()==after&&Sorcery.state(p).cooldown==160&&p.getInventory().getStack(1).getCount()==1,"Replayed packet cannot double damage, cost or cooldown");e.discard();p.discard();c.complete();}

 @GameTest(templateName="witchersbestiary:village_board_arena",batchId="stage21i-paths") public void boundedForestDetourAndImpassableWall(TestContext c)throws Exception{var w=c.getWorld();for(int x=0;x<=64;x++)for(int z=-16;z<=20;z++){var at=c.getAbsolutePos(new BlockPos(x,2,z));w.getChunk(at);w.setBlockState(at.down(),Blocks.GRASS_BLOCK.getDefaultState());for(int y=0;y<16;y++)w.setBlockState(at.up(y),Blocks.AIR.getDefaultState());}var first=c.getAbsolutePos(new BlockPos(6,2,6));var second=c.getAbsolutePos(new BlockPos(56,2,6));w.setBlockState(c.getAbsolutePos(new BlockPos(30,2,6)),Blocks.OAK_LOG.getDefaultState());w.setBlockState(c.getAbsolutePos(new BlockPos(31,3,6)),Blocks.OAK_LEAVES.getDefaultState());var method=Investigations.class.getDeclaredMethod("traversable",net.minecraft.server.world.ServerWorld.class,BlockPos.class,BlockPos.class,boolean.class,Investigations.RouteBudget.class);method.setAccessible(true);c.assertTrue((Boolean)method.invoke(null,w,first,second,true,new Investigations.RouteBudget()),"A loaded forest detour around trunk and low canopy is walkable");for(int z=-8;z<=20;z++)for(int y=2;y<=6;y++)w.setBlockState(c.getAbsolutePos(new BlockPos(30,y,z)),Blocks.STONE.getDefaultState());c.assertTrue(!(Boolean)method.invoke(null,w,first,second,true,new Investigations.RouteBudget()),"Finite search rejects an impassable wall, not a false route");c.complete();}

}
